/**
 * @param {number[]} nums
 * @param {number} k
 * @return {number}
 */
var minimumDifference = function(nums, k) {
    nums.sort((a, b) => a - b);

    const n = nums.length;
    let min = Infinity;

    for (let i = k - 1; i < n; i++) {
        const diff = nums[i] - nums[i - k + 1];

        if (diff < min) {
            min = diff;
        }
    }

    return min === Infinity ? 0 : min;
};
